import{_ as p,a0 as l,w as o,s as r,ao as d,I as i,x as a,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 RHEL 9 上創建本地 Yum/DNF 倉庫 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 9 上創建本地 Yum/DNF 倉庫 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 9 上創建本地 Yum/DNF 倉庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 9 上創建本地 Yum/DNF 倉庫 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220601 How to Create Local Yum-DNF Repository on RHEL 9","title":"如何在 RHEL 9 上創建本地 Yum/DNF 倉庫","tag":"202206","desc":""},"relativePath":"202206/20220601 How to Create Local Yum-DNF Repository on RHEL 9.md","filePath":"[post].md"}'),c={name:"202206/20220601 How to Create Local Yum-DNF Repository on RHEL 9.md"};function u(h,s,g,m,k,b){const e=l("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-rhel-9-上創建本地-yum-dnf-倉庫" tabindex="-1">如何在 RHEL 9 上創建本地 Yum/DNF 倉庫 <a class="header-anchor" href="#如何在-rhel-9-上創建本地-yum-dnf-倉庫" aria-label="Permalink to “如何在 RHEL 9 上創建本地 Yum/DNF 倉庫”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/11/164149y9zzm7kkxwsxgszw.jpg" alt=""></p><p>你好，技術兄弟，最近紅帽發佈了最新的操作系統 RHEL 9，RHEL 9 滿足了混合雲的所有要求。它可以安裝在物理服務器、虛擬機和容器鏡像中。</p><p>當我們沒有訂閲的時候，想安裝軟件包來做實驗，那麼設置本地的 Yum 或 DNF 倉庫將是很方便的。</p><p>在本指南中，我們將介紹如何在 RHEL 9 上使用 DVD 或 ISO 文件一步一步地創建本地 Yum/DNF 資源庫。</p><p>創建本地 Yum/DNF 資源庫的先決條件:</p><ul><li>最小化安裝 RHEL 9 系統</li><li>具有管理權限的 sudo 用户</li><li>RHEL 9 DVD 或 ISO 文件</li></ul><h3 id="_1-掛載-rhel-9-iso-文件或-dvd" tabindex="-1">1）掛載 RHEL 9 ISO 文件或 DVD <a class="header-anchor" href="#_1-掛載-rhel-9-iso-文件或-dvd" aria-label="Permalink to “1）掛載 RHEL 9 ISO 文件或 DVD”">​</a></h3><p>我們假設 RHEL 9 iso 文件已經被複制到系統中。運行下面的掛載命令，將 ISO 文件掛載到 <code>/opt/repo</code> 文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /var/repo</span></span>
<span class="line"><span>$ sudo mount -o loop rhel-baseos-9.0-x86_64-dvd.iso /var/repo/</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Mount-RHEL9-ISO-File-Command.png" alt="Mount-RHEL9-ISO-File-Command"></p><p>如果是 DVD 光盤，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mount /dev/sr0 /var/repo/</span></span></code></pre></div><h3 id="_2-在-etc-yum-repos-d-目錄中創建倉庫文件" tabindex="-1">2）在 /etc/yum.repos.d/ 目錄中創建倉庫文件 <a class="header-anchor" href="#_2-在-etc-yum-repos-d-目錄中創建倉庫文件" aria-label="Permalink to “2）在 /etc/yum.repos.d/ 目錄中創建倉庫文件”">​</a></h3><p>在 <code>/etc/yum.repos.d/</code> 目錄下創建一個名為 “rhel9-local.repo\` 的倉庫文件，內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/yum.repos.d/rhel9-local.repo</span></span>
<span class="line"><span>[Local-BaseOS]</span></span>
<span class="line"><span>name=Red Hat Enterprise Linux 9 - BaseOS</span></span>
<span class="line"><span>metadata_expire=-1</span></span>
<span class="line"><span>gpgcheck=1</span></span>
<span class="line"><span>enabled=1</span></span>
<span class="line"><span>baseurl=file:///var/repo//BaseOS/</span></span>
<span class="line"><span>gpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-redhat-release</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Local-AppStream]</span></span>
<span class="line"><span>name=Red Hat Enterprise Linux 9 - AppStream</span></span>
<span class="line"><span>metadata_expire=-1</span></span>
<span class="line"><span>gpgcheck=1</span></span>
<span class="line"><span>enabled=1</span></span>
<span class="line"><span>baseurl=file:///var/repo//AppStream/</span></span>
<span class="line"><span>gpgkey=file:///etc/pki/rpm-gpg/RPM-GPG-KEY-redhat-release</span></span></code></pre></div><p>保存並關閉該文件。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/RHEL8-Local-Repo-File.png" alt="RHEL8-Local-Repo-File"></p><h3 id="_3-刷新-yum-dnf-和訂閲管理器的緩存" tabindex="-1">3）刷新 Yum/DNF 和訂閲管理器的緩存 <a class="header-anchor" href="#_3-刷新-yum-dnf-和訂閲管理器的緩存" aria-label="Permalink to “3）刷新 Yum/DNF 和訂閲管理器的緩存”">​</a></h3><p>執行以下命令來清理 Yum 或 DNF 和訂閲管理器的緩存。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf clean all</span></span>
<span class="line"><span>$ sudo subscription-manager clean</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/DNF-Subscription-Manager-Clean.png" alt="DNF-Subscription-Manager-Clean"></p><p>在上面的輸出中，我們得到一個警告信息 <code>This system is not registered with an entitlement</code>（系統沒有註冊權限）。所以，為了抑制這個警告信息，編輯文件 <code>/etc/yum/pluginconf.d/subscription-manager.conf</code>，將參數 <code>enabled=1</code> 改為 <code>enabled=0</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/yum/pluginconf.d/subscription-manager.conf</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Disable-Subscription-Parameter-RHEL-9.png" alt="Disable-Subscription-Parameter-RHEL-9"></p><p>保存並退出該文件。</p><h3 id="_4-使用本地倉庫安裝軟件包" tabindex="-1">4）使用本地倉庫安裝軟件包 <a class="header-anchor" href="#_4-使用本地倉庫安裝軟件包" aria-label="Permalink to “4）使用本地倉庫安裝軟件包”">​</a></h3><p>現在我們都準備好測試我們的本地倉庫了。運行下面的命令來查看配置倉庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf repolist</span></span></code></pre></div><p>輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/DNF-Repolist-RHEL-9.png" alt="DNF-Repolist-RHEL-9"></p><p>現在，試試用 <code>dnf</code> 命令通過上面配置的本地倉庫安裝軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install nfs-utils</span></span></code></pre></div><p>輸出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Install-RPM-Package-via-local-repo-rhel9.png" alt="Install-RPM-Package-via-local-repo-rhel9"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Package-Installation-Completion-RHEL9-DNF-Command.png" alt="Package-Installation-Completion-RHEL9-DNF-Command"></p><p>完美，上述輸出證實了 <code>nfs-utils</code> 包及其依賴項已經通過本地配置的 Yum 或 DNF 倉庫成功安裝。</p><p>這就是本指南的全部內容。我希望你覺得它有參考價值。請在下面的評論區發表你的疑問和反饋。</p><hr>`,39)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/create-local-yum-dnf-repository-rhel/"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/create-local-yum-dnf-repository-rhel/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),n(e,{href:"https://github.com/lkxed"},{default:t(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=p(c,[["render",u]]);export{w as __pageData,y as default};
